  "footer.official": "ᱚᱯᱷᱤᱥᱤᱭᱟᱹᱞ ᱯᱳᱨᱴᱟᱞ ᱠᱚ",
  "footer.ncrp": "ᱡᱟᱹᱛᱤᱭᱟᱹᱨᱤ ᱥᱟᱭᱵᱟᱨ ᱠᱨައިᱢ ᱨᱤᱯᱳᱨᱴᱤᱝ ᱯᱳᱨᱴᱟᱞ",
