  "status.degraded": "ᱠᱤᱪᱷᱩ ᱥᱮᱵᱟ ᱠᱚ ᱵᱟᱠᱚ ᱨᱩᱣᱟᱲ ᱮᱫᱟ",
  "status.down": "ᱥᱮᱵᱟ ᱠᱚ ᱵᱚᱸᱫᱽ ᱜᱮᱭᱟ — ᱟᱢᱟᱜ ᱠᱮᱥ ᱫᱚ ᱱᱚᱣᱟ ᱰᱤᱵᱷᱟᱭᱤᱥ ᱨᱮ ᱱᱤᱛ ᱦᱚᱸ ᱨᱩᱠᱷᱤᱭᱟᱹ ᱜᱮ ᱢᱮᱱᱟᱜᱼᱟ",
