  "status.email": "ᱤᱢᱮᱞ",
  "footer.built": "Build What Moves India ᱦᱮᱠᱟᱛᱷᱚᱱ ᱞᱟᱹᱜᱤᱫ ᱛᱮᱭᱟᱨ ᱟᱠᱟᱱᱟ᱾ ᱚᱠᱟ ᱥᱚᱨᱠᱟᱨᱤ ᱦᱚᱲ ᱥᱟᱶ ᱦᱚᱸ ᱵᱟᱝ ᱡᱚᱯᱚᱲᱟᱣ, ᱵᱟᱝ ᱥᱚᱫᱚᱨ ᱟᱨᱵᱟᱝ ᱡᱚᱱᱚᱲ ᱢᱮᱱᱟᱜᱼᱟ᱾ ᱡᱚᱛᱚ ᱨᱮᱯᱷᱚᱨᱮᱱᱥ ᱱᱚᱢᱵᱚᱨ ᱠᱚᱫᱚ ᱱᱚᱠᱚᱞ ᱠᱟᱱᱟ᱾",
  "start.h1": "ᱞᱟᱹᱭ ᱢᱮ ᱪᱮᱫ ᱦᱩᱭ ᱠᱟᱱᱟ᱾",
  "start.sub": "ᱟᱢᱟᱜ ᱟᱡᱟᱜ ᱟᱹᱲᱟᱹ ᱛᱮ, ᱡᱮᱞᱮᱠᱟ ᱟᱢ ᱢᱤᱫ ᱦᱚᱲ ᱪᱮᱛᱟᱱ ᱵᱚᱸᱫᱷᱚᱱ ᱢᱮᱱᱟᱜ ᱢᱟ ᱚᱱᱠᱟ ᱜᱮ ᱵᱩᱡᱷᱟᱹᱣ ᱚᱪᱚᱭᱟ᱾ ᱞᱮᱠᱟ ᱟᱞᱮ ᱢᱤᱫᱴᱟᱹᱝ ᱥᱴᱨᱚᱠᱪᱟᱨᱰ ᱰᱨᱟᱯᱷᱴ ᱞᱮ ᱥᱩᱡᱷᱟᱹᱣᱟ ᱟᱢᱟᱜ ᱧᱮᱞ ᱞᱟᱹᱜᱤᱫ᱾",
  "start.mic": "ᱨᱚᱲ ᱞᱟᱹᱜᱤᱫ ᱡᱚᱵᱮ ᱫᱚᱦᱚᱭ ᱢᱮ",
  "start.micStop": "ᱡᱚᱢᱮᱜᱟ — ᱢᱩᱪᱟᱹᱫ ᱠᱟᱛᱮ ᱵᱟᱲᱟᱜ ᱢᱮ",
  "start.micHint": "ᱨᱚᱲ ᱠᱟᱱᱟ",
  "start.voiceDisclosure": "ᱵᱷᱚᱭᱮᱥ ᱫᱚ ᱟᱢᱟᱜ ᱢᱟᱭᱠᱨᱳᱯᱷᱳᱱ ᱵᱮᱵᱷᱟᱨ ᱮᱫᱟ᱾ ᱵᱨᱟᱣᱡᱟᱨ ᱥᱯᱤᱪ ᱨᱮᱠᱳᱜᱽᱱᱤᱥᱚᱱ ᱫᱚ ᱟᱢᱟᱜ ᱵᱨᱟᱣᱡᱟᱨ ᱵᱷᱮᱱᱰᱚᱨ ᱨᱮᱭᱟᱜ ᱥᱯᱤᱪ ᱥᱚᱨᱵᱷᱤᱥ ᱦᱚᱛᱮᱛᱮ ᱯᱨᱳᱥᱮᱥ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ; ᱨᱮᱠᱳᱨᱰ-ᱚᱰᱤଓ ᱢᱳᱰ ᱫᱚ ᱨᱮᱠᱳᱨᱰᱤᱝ ᱫᱚ Kavach ᱨᱮᱭᱟᱜ ᱠᱚᱱᱯᱷᱤᱜᱟᱨᱰ ᱴᱨᱟᱱᱥᱠᱨᱤᱯᱥᱚᱱ ᱯᱨᱳᱵᱷᱟᱭᱰᱟᱨ ᱴᱷᱮᱱ ᱮ ᱠᱩᱞ ᱮᱫᱟ᱾ ᱚᱰᱤଓ ᱵᱟᱭᱤᱴᱥ ᱫᱚ ᱟᱢᱟᱜ ᱠᱮᱥ ᱯᱷᱟᱭᱤᱞ ᱨᱮ ᱵᱟᱝ ᱡᱚᱲᱟᱜᱼᱟ, ᱢᱮᱱᱠᱷᱟᱱ ᱡᱚᱛᱚ ᱥᱚᱨᱵᱷᱤᱥ ᱨᱮᱭᱟᱜ ᱰᱮᱴᱟ ᱦᱮᱱᱰᱞᱤᱝ ᱫᱚ ᱞᱟᱹᱜᱩ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾ ᱵᱷᱚᱭᱮᱥ ᱯᱨᱳᱥᱮᱥᱤᱝ ᱵᱟᱪᱟᱣ ᱞᱟᱹᱜᱤᱫ ᱚᱱᱚᱠᱷᱚᱱ ᱴᱟᱭᱤᱯ ᱢᱮ᱾",
  "start.voiceConsent": "ᱤᱧ ᱵᱩᱡᱷᱟᱹᱣ ᱮᱫᱟ ᱟᱨ ᱢᱟᱭᱠᱨᱳᱯᱷᱳᱱ ᱮᱠᱥᱮᱥ ᱟᱨ ᱵᱷᱚᱭᱮᱥ ᱴᱨᱟᱱᱥᱠᱨᱤᱯᱥᱚᱱ ᱞᱟᱹᱜᱤᱫ ᱤᱧᱟᱜ ᱨᱟᱹᱡᱤ ᱢᱮᱱᱟᱜᱼᱟ ᱱᱚᱣᱟ ᱥᱴᱮᱴᱢᱮᱱᱴ ᱞᱟᱹᱜᱤᱫ᱾",
  "start.or": "ᱵᱟᱝᱠᱷᱟᱱ ᱚᱞ ᱢᱮ",
  "start.placeholder": "ᱪᱤᱠᱟᱹ ᱞᱮᱠᱟ: ᱮᱭᱟᱭ ᱦᱤᱞᱚᱜ ᱡᱟᱸᱦᱟᱭ ᱦᱚᱲ ᱯᱷᱺᱚᱱ ᱠᱟᱛᱮᱭ ᱢᱮᱱ ᱠᱮᱫᱟ ᱡᱮ ᱩᱱᱤ ᱫᱚ ᱵᱮᱸᱠ ᱠᱷᱚᱱ ᱠᱟᱱᱟᱭ, ᱢᱮᱱ ᱠᱮᱫᱟ ᱤᱧᱟᱜ ᱠᱟᱨᱰ ᱵᱚᱱᱫᱚ ᱟᱠᱟᱱᱟ, OTP ᱠᱷᱚᱡ ᱠᱮᱫᱟ, ᱟᱨ ᱯᱮᱭᱟ ᱴᱨᱟᱱᱡᱮᱠᱥᱚᱱ ᱛᱮ ᱯᱩᱱ ᱜᱮᱞ ᱢᱤᱫ ᱥᱟᱥᱟᱭ ᱴᱟᱠᱟ ᱚᱰᱚᱠ ᱮᱱᱟ᱾",
  "start.examples": "ᱮᱦᱚᱵ ᱮᱢ ᱵᱟᱝ ᱵᱟᱰᱟᱭᱮᱫᱟ? ᱱᱚᱶᱟ ᱠᱚ ᱢᱩᱫᱽ ᱨᱮ ᱢᱤᱫᱴᱟᱹᱝ ᱠᱩᱨᱩᱢᱩᱴᱩ ᱢᱮ",
  "start.ex1": "ᱡᱟᱸᱦᱟᱭ ᱦᱚᱲ ᱤᱧᱟᱜ ᱵᱮᱸᱠ ᱨᱤᱱᱤᱡ ᱠᱟᱱᱟ ᱢᱮᱱ ᱠᱟᱛᱮᱭ ᱯᱷᱺᱚᱱ ᱠᱮᱫᱟ ᱟᱨ OTP ᱮ ᱤᱫᱤ ᱠᱮᱫᱟ",
  "start.ex2": "ᱤᱧ ᱢᱤᱫᱴᱟᱹᱝ ᱣᱮᱵᱽᱥᱟᱭᱤᱴ ᱨᱮ ᱢᱤᱫᱴᱟᱹᱝ ᱯᱷᱺᱚᱱ ᱞᱟᱹᱜᱤᱫ ᱠᱟᱹᱣᱰᱤ ᱮᱢ ᱠᱮᱫᱟ ᱟᱨ ᱚᱱᱟ ᱫᱚ ᱵᱟᱝ ᱥᱮᱴᱮᱨ ᱞᱮᱱᱟ",
  "start.ex3": "ᱯᱩᱞᱤᱥ ᱠᱟᱱᱟ ᱢᱮᱱ ᱠᱟᱛᱮ ᱢᱤᱫᱴᱟᱹᱝ ᱵᱷᱤᱰᱤᱭᱳ ᱠᱚᱞ ᱠᱟᱛᱮ ᱠᱚ ᱢᱮᱱ ᱠᱮᱫᱟ ᱡᱮ ᱤᱧ ᱫᱚ ᱰᱤᱡᱤᱴᱟᱞ ᱟᱨᱮᱥᱴ ᱨᱮ ᱢﯾᱱᱟᱹᱧᱟ",
  "start.ex4": "ᱡᱟᱸᱦᱟᱭ ᱦᱚᱲ ᱤᱧᱟᱜ ᱪᱚᱵᱤ ᱠᱚ ᱵᱮᱵᱷᱟᱨ ᱠᱟᱛᱮ ᱢᱤᱫᱴᱟᱹᱝ ᱵᱷᱩᱜᱟᱹᱜ Instagram ᱮᱠᱟᱩᱱᱴ ᱮ ᱵᱮᱱᱟᱣ ᱠᱮᱫᱟ",
