  "start.saveError": "ᱱᱚᱣᱟ ᱵᱨᱟᱣᱡᱟᱨ ᱫᱚ ᱠᱮᱥ ᱯᱷᱟᱭᱤᱞ ᱵᱟᱭ ᱥᱟᱧᱪᱟᱣ ᱫᱟᱲᱮᱭᱟᱫᱟ᱾ ᱱᱚᱣᱟ ᱯᱮᱡᱽ ᱠᱷᱩᱞᱟᱹ ᱜᱮ ᱫᱚᱦᱚᱭ ᱢᱮ, ᱠᱤᱪᱷᱩ ᱰᱤᱵᱷᱟᱭᱤᱥ ᱥᱴᱚᱨᱮᱡᱽ ᱠᱷᱟᱹᱞᱤ ᱢᱮ ᱵᱟᱝᱠᱷᱟᱱ ᱵᱨᱟᱣᱡᱟᱨ ᱯᱨᱟᱭᱵᱷᱮᱥᱤ ᱥᱮᱴᱤᱝᱥ ᱵᱚᱫᱚᱞ ᱢᱮ, ᱚᱱᱟ ᱛᱟᱭᱚᱢ ᱠᱮᱥ ᱵᱮᱱᱟᱣ ᱨᱩᱣᱟᱹᱲ ᱨᱮᱭᱟᱜ ᱠᱩᱨᱩᱢᱩᱴᱩ ᱢᱮ᱾",
