  "intake.vaaniBrowserAgent": "Kavach Saathi",
  "intake.vaaniBrowserYou": "ᱟᱢ",
  "intake.vaaniBrowserError": "ᱠᱚᱞ ᱵᱟᱝ ᱡᱚᱲᱟᱣ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾ ᱟᱢᱟᱜ ᱢᱟᱢᱞᱟ ᱨᱮ ᱪᱮᱫ ᱦᱚᱸ ᱵᱟᱝ ᱚᱨᱥᱚᱝᱼᱟ, ᱟᱨ ᱚᱱᱟ ᱵᱚᱫᱚᱞ ᱛᱮ ᱟᱢ ᱚᱞ ᱵᱟᱲᱟ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
  "intake.vaaniCredit": "ᱨᱚᱲ ᱮᱫᱟᱭ",
  "intake.vaaniCreditLink": "Vaani AI Research — ᱩᱱᱠᱩᱣᱟᱜ ᱥᱟᱭᱤᱴ ᱢᱤᱫ ᱱᱟᱣᱟ ᱴᱮᱵᱽ ᱨᱮ ᱡᱷᱤᱡ ᱠᱟᱱᱟ",
