  "intake.vaaniLangQ": "ᱟᱢ ᱫᱚ ᱚᱠᱟ ᱯᱟᱹᱨᱥᱤ ᱛᱮ ᱨᱚᱲ ᱥᱟᱱᱟᱭᱮᱫ ᱢᱮᱭᱟ?",
  "intake.vaaniLangSub": "Kavach Saathi ᱫᱚ ᱟᱢ ᱡᱟᱦᱟᱸ ᱯᱟᱹᱨᱥᱤ ᱢᱮᱱ ᱠᱮᱫᱟ ᱚᱱᱟ ᱛᱮᱜᱮ ᱟᱢ ᱥᱟᱶ ᱮ ᱨᱚᱲᱟ᱾",
  "intake.vaaniLangMore": "ᱥᱟᱱᱟᱢ ᱯᱟᱹᱨᱥᱤ ᱠᱚ ᱩᱫᱩᱜ ᱢᱮ",
  "intake.vaaniLangCancel": "ᱵᱟᱛᱟᱣ",
  "intake.vaaniBrowserMicHint": "ᱟᱢᱟᱜ ᱢᱟᱭᱠᱨᱳᱯᱷᱳᱱ ᱵᱮᱵᱷᱟᱨ ᱞᱟᱹᱜᱤᱫ ᱟᱢᱟᱜ ᱵᱨᱟᱣᱡᱟᱨ ᱠᱩᱞᱤ ᱢᱮ᱾ ᱡᱩᱫᱤ ᱵᱟᱢ ᱵᱟᱹᱜᱤᱭᱟᱜᱼᱟ ᱪᱮᱫ ᱦᱚᱸ ᱵᱟᱝ ᱟᱸᱡᱚᱢᱚᱜᱼᱟ, ᱟᱨ ᱡᱟᱦᱟᱸ ᱚᱠᱛᱚ ᱨᱮᱜᱮ ᱟᱢ ᱠᱚᱞ ᱢᱤᱣᱴ ᱥᱮ ᱢᱩᱪᱟᱹᱫ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
  "intake.vaaniBrowserMicDenied": "ᱟᱢᱟᱜ ᱵᱨᱟᱣᱡᱟᱨ ᱢᱟᱭᱠᱨᱳᱯᱷᱳᱱ ᱮ ᱮᱥᱮᱫ ᱟᱠᱟᱫᱟ, ᱚᱱᱟᱛᱮ ᱠᱚᱞ ᱨᱮ ᱟᱢᱟᱜ ᱠᱟᱛᱷᱟ ᱵᱟᱝ ᱟᱸᱡᱚᱢᱚᱜ ᱠᱟᱱᱟ᱾ ᱱᱚᱣᱟ ᱥᱟᱭᱤᱴ ᱞᱟᱹᱜᱤᱫ ᱢᱟᱭᱠᱨᱳᱯᱷᱳᱱ ᱵᱮᱵᱷᱟᱨ ᱟᱭ ᱢᱮ ᱟᱨ ᱨᱩᱣᱟᱹᱲ ᱠᱩᱨᱩᱢᱩᱴᱩ ᱢེ, ᱥᱮ ᱚᱱᱟ ᱵᱚᱫᱚᱞ ᱛᱮ ᱚᱞ ᱜᱮ ᱪᱟᱞᱟᱜ ᱢᱮ᱾",
  "intake.vaaniBrowserAfter": "ᱡᱚᱠᱷᱚᱡ ᱟᱢ ᱢᱩᱪᱟᱹᱫ ᱢᱮ, ᱨᱮᱠᱚᱨᱰᱤᱝ ᱟᱨ ᱚᱞ ᱟᱠᱟᱱ ᱠᱟᱛᱷᱟ ᱫᱚ ᱠᱚᱞ ᱞᱟᱛᱟᱨ ᱨᱮ ᱟᱢᱟᱜ ᱢᱟᱢᱞᱟ ᱥᱟᱠᱟᱢ ᱨᱮ ᱧᱮᱚᱜᱼᱟ᱾",
  "vdemo.kicker": "ᱢᱤᱫᱴᱟᱹᱝ ᱥᱟᱹᱨᱤ ᱠᱚᱞ",
  "vdemo.h2": "ᱠᱚᱞ ᱮᱢᱚᱜᱤᱡ ᱫᱚ ᱦᱤᱱᱫᱤ ᱛᱮᱭ ᱨᱚᱲ ᱠᱮᱫᱟ᱾ ᱱᱚᱣᱟ ᱫᱚ ᱧᱩᱛᱩᱢ ᱮ ᱥᱟᱵ ᱠᱮᱫᱟ, ᱚᱱᱟᱭ ᱵᱮᱵᱷᱟᱨ ᱠᱮᱫᱟ, ᱟᱨ ᱯᱷᱚᱨᱚᱢ ᱮ ᱯᱮᱨᱮᱡ ᱠᱮᱫᱟ᱾",
  "vdemo.body": "ᱱᱚᱣᱟ ᱫᱚ ᱡᱟᱦᱟᱸ ᱱᱟᱜ ᱰᱷᱚᱝ ᱫᱚ ᱵᱟᱝ ᱠᱟᱱᱟ᱾ ᱱᱚᱣᱟ ᱫᱚ Kavach Saathi ᱥᱟᱶ ᱢᱤᱫᱴᱟᱹᱝ ᱨᱤᱠᱚᱨᱰ ᱟᱠᱟᱱ ᱠᱚᱞ ᱠᱟᱱᱟ, ᱡᱟᱦᱟᱸ ᱫᱚ ᱡᱟᱦᱟᱸ ᱞᱮᱠᱟ ᱦᱩᱭ ᱞᱮᱱᱟ ᱚᱝᱠᱟ ᱜᱮ ᱟᱸᱡᱚᱢᱚᱜ ᱠᱟᱱᱟ — ᱵᱟᱨ ᱢᱟᱦᱟᱸ ᱢᱟᱬᱟᱝ ᱨᱮ ᱢᱤᱫᱴᱟᱹᱝ ₹10,000 ᱨᱮᱭᱟᱜ ᱠᱟᱨᱰ ᱯᱮᱢᱮᱱᱴ ᱵᱟᱝ ᱥᱟᱹᱜᱩᱱ ᱞᱮᱱᱟ, ᱟᱨ ᱢᱤᱫ ᱵᱟᱰᱟᱭ ᱵᱟᱹᱱᱩᱜ ᱦᱚᱲ ᱱᱤᱛ ᱦᱚᱸ ᱤᱢᱮᱞ ᱛᱮ ᱴᱟᱠᱟᱭ ᱠᱷᱚᱡ ᱠᱟᱱᱟ᱾ ᱠᱚᱞ ᱮᱢᱚᱜᱤᱡ ᱫᱚ ᱢᱤᱫ ᱟᱠᱷᱚᱨ ᱦᱚᱸ ᱵᱟᱭ ᱴᱟᱭᱤᱯ ᱞᱮᱫᱟ, ᱪᱮᱫ ᱛᱷᱚᱠ ᱦᱚᱸ ᱵᱟᱭ ᱵᱟᱪᱷᱟᱣ ᱞᱮᱫᱟ, ᱪᱮᱫ ᱯᱷᱚᱨᱚᱢ ᱦᱚᱸ ᱵᱟᱭ ᱧᱮᱞ ᱞᱮᱫᱟ᱾",
  "vdemo.listen": "ᱠᱚᱞ ᱟᱸᱡᱚᱢ ᱢᱮ",
  "vdemo.transcript": "ᱪᱮᱫ ᱠᱚ ᱨᱚᱲ ᱦᱩᱭ ᱞᱮᱱᱟ",
  "vdemo.extracted": "ᱪᱮᱫ ᱠᱚ ᱟᱡ ᱛᱮᱜᱮ ᱠᱚ ᱯᱮᱨᱮᱡ ᱠᱮᱫᱟ",
  "vdemo.extractedSub": "ᱞᱟᱛᱟᱨ ᱨᱮᱭᱟᱜ ᱥᱟᱱᱟᱢ ᱢᱟᱱ ᱠᱚᱫᱚ ᱪᱮᱛᱟᱱ ᱨᱮᱭᱟᱜ ᱨᱚᱲ ᱠᱷᱚᱱ ᱦᱟᱛᱟᱣ ᱟᱠᱟᱱᱟ᱾ ᱪᱮᱫ ᱦᱚᱸ ᱵᱟᱝ ᱴᱟᱭᱤᱯ ᱟᱠᱟᱱᱟ᱾",
  "vdemo.agent": "Kavach Saathi",
  "vdemo.caller": "ᱠᱚᱞ ᱮᱢᱚᱜᱤᱡ",
  "vdemo.statReply": "ᱛᱟᱞᱟᱢᱟᱞᱟ ᱨᱩᱣᱟᱲ",
  "vdemo.statFields": "ᱥᱟᱵ ᱟᱠᱟᱱ ᱠᱟᱛᱷᱟ ᱠᱚ",
  "vdemo.statLangs": "ᱯᱟᱹᱨᱥᱤ ᱠᱚ, ᱢᱤᱫᱴᱟᱹᱝ ᱮᱞ",
  "vdemo.statTyping": "ᱯᱮᱨᱮᱡ ᱞᱟᱹᱜᱤᱫ ᱯᱷᱚᱨᱚᱢ ᱴᱷᱟᱶ",
  "vdemo.why1": "ᱱᱚᱣᱟ ᱫᱚ ᱢᱤᱫ ᱥᱮᱠᱮᱱᱰ ᱟᱨ ᱚᱱᱟ ᱨᱮᱭᱟᱜ ᱟᱫᱷᱟ ᱜᱟᱱ ᱨᱮᱭᱮ ᱨᱩᱣᱟᱲᱟ, ᱚᱱᱟᱛᱮ ᱪᱮᱫ ᱦᱚᱲ ᱦᱚᱸ ᱪᱩᱯ ᱨᱮ ᱵᱟᱠᱚ ᱛᱟᱦᱮᱸ ᱠᱚᱜᱼᱟ᱾",
  "vdemo.why2": "ᱱᱚᱣᱟ ᱫᱚ ᱠᱩᱠᱞᱤ ᱠᱮᱫᱟ ᱪᱮᱫ ᱠᱚ ᱢᱮᱛᱟᱭᱟ, ᱦᱤᱱᱫᱤ ᱛᱮ “प्रणव” ᱮ ᱟᱸᱡᱚᱢ ᱠᱮᱫᱟ, ᱟᱨ ᱚᱱᱟ ᱧᱩᱛᱩᱢ ᱜᱮ ᱵᱟᱹᱠᱤ ᱠᱚᱞ ᱨᱮᱭᱮ ᱵᱮᱵᱷᱟᱨ ᱠᱮᱫᱟ᱾",
  "vdemo.why3": "ᱱᱚᱣᱟ ᱫᱚ ᱫᱚᱥᱟᱨ ᱥᱟᱦᱮᱫ ᱨᱮᱜᱮ ᱠᱚᱞ ᱮᱢᱚᱜᱤᱡ 1930 ᱟᱨ ᱩᱱᱠᱩᱣᱟᱜ ᱵᱮᱸᱠ ᱛᱮᱭ ᱵᱷᱮᱡᱟ ᱠᱮᱫᱮᱭᱟ, ᱮᱴᱟᱜ ᱪᱮᱫ ᱦᱚᱸ ᱠᱩᱠᱞᱤ ᱢᱟᱬᱟᱝ ᱨᱮ᱾",
  "vdemo.why4": "ᱱᱚᱰᱮ ᱪᱮᱫ ᱦᱚᱸ ᱡᱟᱦᱟᱸᱭ ᱴᱷᱮᱱ ᱦᱚᱸ ᱵᱟᱝ ᱫᱚᱦᱚ ᱟᱠᱟᱱᱟ᱾ ᱠᱚᱞ ᱨᱮ ᱚᱱᱟ ᱜᱮᱠᱚ ᱨᱚᱲ ᱮᱫᱟ, ᱟᱨ ᱞᱤᱧ ᱦᱚᱸ ᱚᱱᱠᱟ ᱜᱮᱞᱤᱧ ᱢᱮᱱᱮᱫᱟ᱾",
  "vdemo.more": "ᱠᱚᱞ ᱨᱮᱭᱟᱜ ᱵᱟᱹᱠᱤ ᱦᱟᱹᱴᱤᱧ ᱩᱫᱩᱜ ᱢᱮ",
  "vdemo.openCase": "ᱱᱚᱣᱟ ᱠᱚᱞ ᱛᱮ ᱡᱟᱦᱟᱸ ᱠᱮᱥ ᱵᱮᱱᱟᱣ ᱟᱠᱟᱱᱟ ᱚᱱᱟ ᱡᱷᱤᱡ ᱢᱮ",
  "vdemo.openCaseSub": "ᱜᱚᱴᱟ ᱨᱮᱠᱚᱨᱰ — ᱨᱩᱣᱟᱲ ᱧᱟᱢ ᱨᱮᱭᱟᱜ ᱚᱠᱛᱚ, 1930 ᱥᱠᱨᱤᱯᱴ, NCRP ᱠᱚᱢᱯᱞᱮᱱᱴ, ᱨᱩᱠᱷᱤᱭᱟᱹ ᱯᱟᱲᱪᱟᱣ ᱛᱟᱹᱞᱠᱟᱹ — ᱚᱱᱟ ᱨᱚᱲ ᱠᱷᱚᱱ ᱟᱨ ᱮᱴᱟᱜ ᱪᱮᱫ ᱠᱷᱚᱱ ᱦᱚᱸ ᱵᱟᱝ᱾",
  "vdemo.disclaimer": "ᱱᱚᱣᱟ ᱫᱮᱠᱷᱟᱣ ᱞᱟᱹᱜᱤᱫ ᱫᱚ ᱵᱟᱰᱟᱭ ᱚᱪᱚ ᱠᱟᱛᱮ ᱨᱤᱠᱳᱨᱰ ᱟᱠᱟᱱᱟ᱾ ᱧᱩᱛᱩᱢ ᱟᱨ ᱪᱤᱱᱦᱟᱹ ᱠᱚᱫᱚ ᱠᱚᱞᱚᱨ ᱟᱜ ᱟᱡᱟᱜ ᱴᱮᱥᱴ ᱰᱮᱴᱟ ᱠᱟᱱᱟ᱾",
  "case.emailSent": "ᱱᱚᱣᱟ ᱠᱮᱥ ᱨᱮᱱᱟᱜ ᱢᱤᱫ ᱱᱚᱠᱚᱞ, ᱟᱢᱟᱜ ᱨᱮᱯᱷᱚᱨᱮᱱᱥ ᱟᱨ ᱫᱟᱦᱟᱲ ᱛᱟᱭᱚᱢ ᱠᱟᱹᱢᱤ ᱥᱟᱶᱛᱮ, ᱤᱢᱮᱞ ᱦᱚᱪᱚ ᱟᱠᱟᱱᱟ",
  "call.title": "Kavach Saathi ᱥᱟᱶ ᱟᱢᱟᱜ ᱠᱚᱞ",
  "call.sub": "ᱨᱮᱠᱚᱨᱰᱤᱝ ᱟᱨ ᱚᱞ ᱟᱠᱟᱱ ᱠᱟᱛᱷᱟ ᱫᱚ ᱨᱚᱲ ᱮᱢᱤᱡ ᱴᱷᱮᱱ ᱠᱷᱚᱱ ᱦᱤᱡᱩᱜ ᱠᱟᱱᱟ᱾ ᱮᱡᱮᱱᱴ ᱡᱟᱦᱟᱸᱭ ᱵᱩᱡᱷᱟᱹᱣ ᱟᱠᱟᱫᱟ ᱚᱱᱟ ᱫᱚ ᱢᱤᱫ ᱰᱨᱟᱯᱷᱴ ᱠᱟᱱᱟ ᱡᱚᱠᱷᱚᱡ ᱟᱢ ᱱᱚᱣᱟ ᱵᱟᱢ ᱵᱤᱠᱟᱹᱣᱟ᱾",
  "call.none": "ᱱᱚᱣᱟ ᱡᱤᱱᱤᱥ ᱨᱮ ᱱᱤᱛ ᱫᱷᱟᱹᱵᱤᱡ ᱡᱟᱦᱟᱸᱱᱟᱜ ᱨᱚᱲ ᱠᱚᱞ ᱵᱟᱱᱩᱜᱼᱟ᱾ ᱤᱱᱴᱮᱠ ᱥᱟᱠᱟᱢ ᱠᱷᱚᱱ ᱢᱤᱫᱴᱟᱹᱝ ᱮᱦᱚᱵ ᱢᱮ ᱟᱨ ᱱᱚᱸᱰᱮ ᱧᱮᱞᱚᱜᱼᱟ᱾",
  "call.pending": "ᱮᱢᱤᱡ ᱫᱚ ᱱᱚᱣᱟ ᱠᱚᱞ ᱵᱮᱱᱟᱣ ᱢᱩᱪᱟᱹᱫ ᱟᱠᱟᱫᱟ ᱵᱟᱝ᱾ ᱯᱷᱳᱱ ᱫᱚᱦᱚ ᱠᱟᱛᱮ ᱱᱚᱣᱟ ᱫᱚ ᱢᱤᱫᱴᱟᱹᱝ ᱴᱤᱯᱤᱡ ᱦᱟᱛᱟᱣ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
  "call.refresh": "ᱦᱤᱥᱟᱹᱵᱽ ᱨᱩᱣᱟᱹᱲ ᱢᱮ",
  "call.recording": "ᱨᱮᱠᱚᱨᱰᱤᱝ",
  "call.recordingNone": "ᱱᱚᱣᱟ ᱠᱚᱞ ᱞᱟᱹᱜᱤᱫ ᱡᱟᱦᱟᱸᱱᱟᱜ ᱨᱮᱠᱚᱨᱰᱤᱝ ᱵᱟᱱᱩᱜᱼᱟ᱾",
  "call.recordingConsent": "ᱨᱮᱠᱚᱨᱰᱤᱝ ᱫᱚ ᱚᱱᱟ ᱞᱟᱹᱜᱤᱫ ᱢᱮᱱᱟᱜᱼᱟ ᱪᱮᱫᱟᱜ ᱥᱮ ᱟᱢᱮᱢ ᱨᱟᱡᱤ ᱞᱮᱱᱟ᱾ ᱠᱟᱵᱷᱚᱪ ᱫᱚ ᱟᱡᱟᱜ ᱪᱮᱫ ᱱᱚᱠᱚᱞ ᱦᱚᱸ ᱵᱟᱭ ᱫᱚᱦᱚᱭᱟ᱾",
