  "access.body": "ᱟᱢᱟᱜ ᱠᱮᱥ ᱫᱚ ᱥᱟᱧᱪᱟᱣ ᱢᱮᱱᱟᱜᱼᱟ ᱡᱟᱦᱟᱛᱮ ᱟᱢ ᱮᱴᱟᱜ ᱠᱚᱢᱯᱤᱭᱩᱴᱚᱨ ᱥᱮ ᱢᱳᱵᱟᱭᱤᱞ ᱨᱮ ᱨᱩᱣᱟᱹᱲ ᱦᱮᱡ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ — ᱢᱤᱫᱴᱟᱹᱝ ᱯᱷᱳᱱ, ᱜᱟᱛᱮᱭᱟᱜ ᱞᱮᱯᱴᱚᱯ, ᱥᱮ ᱱᱚᱣᱟ ᱵᱨᱟᱣᱡᱚᱨ ᱡᱚᱠᱷᱚᱱ ᱯᱷᱟᱨᱪᱟ ᱦᱩᱭ ᱟᱠᱟᱱᱟ᱾ ᱩᱭᱦᱟᱹᱨ ᱫᱚᱦᱚ ᱞᱟᱹᱜᱤᱫ ᱚᱠᱟ ᱯᱟᱥᱣᱚᱨᱰ ᱦᱚᱸ ᱵᱟᱹᱱᱩᱜᱼᱟ: ᱱᱚᱣᱟ ᱞᱤᱸᱠ ᱜᱮ ᱵᱚᱞᱚᱱ ᱫᱩᱣᱟᱹᱨ ᱠᱟᱱᱟ ᱟᱨ ᱱᱚᱣᱟ ᱜᱮ ᱢᱤᱫᱴᱟᱹᱝ ᱵᱚᱞᱚᱱ ᱫᱩᱣᱟᱹᱨ ᱠᱟᱱᱟ᱾",
  "access.warning": "ᱡᱟᱦᱟᱸᱭ ᱴᱷᱮᱱ ᱱᱚᱣᱟ ᱞᱤᱸᱠ ᱢᱮᱱᱟᱜᱼᱟ ᱩᱱᱤ ᱫੋ ᱱᱚᱣᱟ ᱠᱮᱥ ᱯᱟᱲᱦᱟᱣ ᱫᱟᱲᱮᱭᱟᱜᱼᱟᱭ, ᱴᱟᱠᱟ ᱞᱮᱠᱷᱟ, ᱮᱠᱟᱣᱩᱱᱴ ᱵᱤᱵᱚᱨᱚᱱ ᱟᱨ ᱟᱢ ᱪᱮᱫ ᱮᱢ ᱢᱮᱱ ᱟᱠᱟᱫᱟ ᱚᱱᱟ ᱦᱚᱸ᱾ ᱱᱚᱣᱟ ᱫᱚ ᱟᱡ ᱛᱮᱜᱮ ᱵᱷᱮᱜᱟᱨ ᱢᱮ, ᱟᱨ ᱚᱠᱚᱭ ᱴᱷᱮᱱ ᱦᱚᱸ ᱵᱟᱝᱟ ᱡᱟᱦᱟᱸᱭ ᱴᱷᱮᱱ ᱠᱮᱥ ᱩᱫᱩᱜ ᱫᱚ ᱵᱟᱢ ᱠᱷᱚᱡᱟ᱾",
