  "nav.compare": "ᱛᱩᱞᱟᱹᱡᱚᱠᱷᱟ",
  "check.kicker": "ᱴᱟᱠᱟ ᱵᱟᱢ ᱮᱢ ᱢᱟᱬᱟᱝ ᱨᱮ",
