  "check.sub": "ᱠᱷᱚᱵᱚᱨ, ᱞᱤᱸᱠ, UPI ID ᱵᱟᱝᱠᱷᱟᱱ ᱱᱚᱢᱵᱚᱨ ᱯᱮᱥᱴ ᱢᱮ᱾ ᱟᱞᱮ ᱞᱮ ᱢᱟᱢᱟ ᱱᱚᱶᱟ ᱨᱮ ᱪᱮᱫ ᱮᱲᱮ ᱢᱮᱱᱟᱜᱼᱟ — ᱴᱟᱠᱟ ᱪᱟᱞᱟᱜ ᱢᱟᱬᱟᱝ ᱨᱮ, ᱡᱚᱠᱷᱚᱱ ᱟᱢᱟᱜ ᱴᱷᱟᱹᱣᱠᱟᱹ ᱛᱟᱦᱮᱸᱱᱟ᱾",
