  "check.again": "ᱵᱟᱝᱠᱷᱟᱱ ᱮᱴᱟᱜ ᱪᱮᱫ ᱜᱮ ᱧᱮᱞ ᱢᱮ",
  "check.tryTitle": "ᱵᱟᱝᱠᱷᱟᱱ ᱱᱚᱶᱟ ᱠᱚ ᱢᱩᱫᱽ ᱨᱮ ᱢᱤᱫᱴᱟᱹᱝ ᱨᱮ ᱠᱩᱨᱩᱢᱩᱴᱩᱭ ᱢᱮ",
  "check.ex1": "ᱚᱱᱚᱨᱟ ᱜᱚᱲᱚᱢᱦᱟᱲᱟ, ᱟᱢᱟᱜ SBI ᱮᱠᱟᱭᱩᱸᱴ 24 ᱴᱟᱲᱟᱝ ᱵᱷᱤᱛᱨᱤ ᱨᱮ ᱵᱚᱸᱫᱚᱜᱼᱟ᱾ http://sbi-kyc-verify.xyz ᱨᱮ ᱟᱢᱟᱜ KYC ᱞᱮᱠᱤᱱ ᱟᱯᱰᱮᱴ ᱢᱮ ᱵᱟᱝᱠᱷᱟᱱ 9812345670 ᱨᱮ ᱠᱚᱞ ᱢᱮ᱾",
  "check.ex2": "ᱤᱱᱥᱯᱮᱠᱴᱚᱨ ᱥᱚᱨᱢᱟ ᱠᱟᱱᱟᱭ, CBI ᱢᱩᱢᱵᱟᱭ᱾ ᱟᱢᱟᱜ ᱧᱩᱛᱩᱢ ᱛᱮ ᱢᱤᱫᱴᱟᱹᱝ ᱯᱟᱨᱥᱚᱞ ᱨᱮ ᱱᱟᱨᱠᱳᱴᱤᱠᱥ ᱧᱟᱢ ᱟᱠᱟᱱᱟ᱾ ᱟᱢ ᱫᱚ ᱰᱤᱡᱤᱴᱟᱞ ᱟᱨᱮᱥᱴ ᱨᱮ ᱢᱮᱱᱟᱢᱟ᱾ ᱱᱚᱶᱟ ᱵᱷᱤᱰᱤᱭᱳ ᱠᱚᱞ ᱨᱮᱜᱮ ᱛᱟᱦᱮᱸᱱ ᱢᱮ ᱟᱨ ᱵᱟᱢ ᱜᱚᱴ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ ᱵᱟᱝᱠᱷᱟᱱ ᱦᱚᱲ ᱵᱟᱢ ᱞᱟᱹᱭ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
  "check.ex3": "ᱵᱷᱟᱜᱮ ᱠᱟᱛᱷᱟ! ᱟᱢᱟᱜ Rs 12,499 ᱨᱮᱱᱟᱜ Amazon ᱨᱤᱯᱷᱚᱸᱰ ᱯᱟᱥ ᱮᱱᱟ᱾ ᱚᱱᱟ ᱧᱟᱢ ᱞᱟᱹᱜᱤᱫ ᱛᱮ refund.amazon@okpay ᱨᱮ Rs 499 ᱨᱮᱱᱟᱜ ᱨᱤᱯᱷᱚᱸᱰᱮᱵᱚᱞ ᱯᱨᱚᱥᱮᱥᱤᱝ ᱯᱷᱤ ᱮᱢ ᱢᱮ",
