  "check.v.caution": "ᱥᱚᱪᱮᱛ ᱛᱟᱦᱮᱸᱱ ᱢᱮ᱾ ᱱᱚᱶᱟ ᱨᱮᱱᱟᱜ ᱛᱤᱱᱟᱹᱜ ᱜᱟᱱ ᱫᱚ ᱴᱷᱤᱠ ᱵᱟᱝ ᱧᱮᱞᱚᱜ ᱠᱟᱱᱟ᱾",
