  "doc.mrm.t": "ᱴᱟᱠᱟ ᱨᱩᱣᱟᱹᱲ ᱨᱮᱭᱟᱜ ᱟᱨᱫᱟ",
  "doc.mrm.b": "mrm-ncrp.mha.gov.in ᱨᱮ ᱡᱚᱛᱚ ᱢᱟᱱ ᱵᱚᱞᱚ ᱦᱩᱭᱩᱜᱼᱟ, ᱡᱟᱦᱟᱸ ᱞᱮᱠᱟ ᱯᱳᱨᱴᱟᱞ ᱠᱷᱚᱱ ᱠᱚ ᱠᱷᱚᱡᱚᱜ ᱠᱱᱟ, ᱚᱱᱟ ᱥᱟᱶᱛᱮ ᱟᱢᱤᱡ ᱡᱚᱸᱪ ᱚᱯᱷᱤᱥᱚᱨ ᱴᱷᱮᱱ ᱪᱷᱟᱹᱲ ᱚᱨᱰᱟᱨ ᱞᱟᱹᱜᱤᱫ ᱮᱢ ᱠᱟᱛᱷᱟ᱾",
  "doc.ombudsman.t": "Ombudsman ᱠᱚᱢᱯᱮᱞᱮᱱᱴ",
  "doc.ombudsman.b": "ᱱᱚᱣᱟ ᱫᱚ ᱵᱮᱵᱷᱟᱨ ᱢᱮ ᱠᱷᱟᱹᱞᱤ ᱯᱩᱭᱞᱩ ᱨᱮᱜᱩᱞᱮᱴᱮᱰ ᱮᱱᱴᱤᱴᱤ ᱴᱷᱮᱱ ᱠᱚᱢᱯᱮᱱᱤ ᱠᱟᱛᱮ ᱟᱨ ᱵᱟᱝ ᱵᱷᱟᱹᱜᱤ ᱨᱩᱣᱟᱹᱲ ᱧᱟᱢ ᱛᱟᱭᱚᱢ, ᱥᱮ ᱞᱟᱹᱜᱩ ᱟᱠᱟᱱ 30-ᱢᱟᱦᱟᱸ-ᱥᱮ-ᱡᱟᱹᱥᱛᱤ ᱨᱩᱣᱟᱹᱲ ᱚᱠᱛᱚ ᱛᱟᱭᱚᱢ᱾ ᱵᱷᱟᱜᱮ 90-ᱢᱟᱦᱟᱸ ᱵᱷᱟᱡᱟ ᱥᱤᱢᱟᱹ ᱟᱨ ᱡᱚᱛᱚ ᱟᱸᱰᱚᱠᱮᱞᱮᱡᱽᱢᱮᱱᱴ ᱢᱟᱦᱟᱸ ᱧᱮᱞ ᱢᱮ᱾",
  "ask.t": "ᱟᱢᱟᱜ ᱠᱮᱥ ᱵᱟᱵᱚᱛ ᱠᱩᱠᱞᱤ ᱢᱮ",
