  "begin.chooseH": "ᱪᱮᱫ ᱞᱮᱠᱟᱛᱮᱢ ᱞᱟᱹᱭ ᱟᱵᱚᱣᱟ ᱪᱮᱫ ᱦᱩᱭ ᱞᱮᱱᱟ?",
  "begin.chooseSub": "ᱡᱟག་ ᱞᱮᱠᱟ ᱛᱮᱜᱮ, ᱢᱤᱫ ᱞᱮᱠᱟᱱ ᱠᱮᱥ ᱜᱮ ᱵᱮᱱᱟᱣᱜᱼᱟ᱾ ᱛᱟᱭᱚᱢ ᱛᱮ ᱟᱢ ᱵᱚᱫᱚᱞ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
  "begin.voiceH": "ᱠᱚᱵᱚᱪ ᱥᱟᱛᱷᱤ (Kavach Saathi) ᱥᱟᱶ ᱜᱟᱞᱢᱟᱨᱟᱣ ᱢᱮ",
  "begin.voiceNote": "ᱟᱢᱟᱜ ᱟᱡᱟᱜ ᱯᱟᱹᱨᱥᱤ ᱛᱮ ᱨᱚᱲ ᱢᱮ᱾ ᱯᱷᱳᱱ ᱱᱚᱢᱵᱚᱨ ᱨᱮᱱᱟᱜ ᱞᱟᱹᱠᱛᱤ ᱵᱟᱹᱱᱩᱜᱼᱟ — ᱱᱚᱣᱟ ᱫᱚ ᱱᱚᱣᱟ ᱴᱮᱵᱽ ᱨᱮᱜᱮ ᱠᱟᱹᱢᱤᱭᱟ᱾",
  "begin.chatH": "ᱚᱞ ᱠᱟᱛᱮ ᱵᱷᱮᱜᱟᱨ ᱢᱮ",
  "begin.chatNote": "ᱢᱤᱫ ᱵᱟᱰᱟᱭ ᱪᱟᱴ, ᱟᱢᱟᱜ ᱟᱡᱟᱜ ᱜᱟᱱ ᱛᱮ᱾ ᱣᱚᱴᱥᱮᱯ (WhatsApp) ᱨᱮ ᱪᱮᱫ ᱦᱚᱸ ᱵᱟᱝ ᱵᱷᱮᱜᱟᱨ ᱠᱟᱱᱟ᱾",
  "begin.formLink": "ᱯᱷᱚᱨᱚᱢ ᱮᱢ ᱠᱷᱚᱡᱟ? ᱢᱚᱬᱮ-ᱛᱷᱚᱠ ᱵᱷᱚᱨᱥᱚᱱ ᱵᱮᱵᱷᱟᱨ ᱢᱮ",
  "begin.back": "ᱨᱩᱣᱟᱹᱲ",
  "begin.boundaryNote": "ᱟᱞᱮ ᱫᱚ ᱚᱱᱟ ᱜᱮᱞᱮ ᱠᱩᱞᱤᱭᱮᱫᱟ ᱡᱟᱦᱟᱸ ᱟᱢᱟᱜ ᱠᱮᱥ ᱨᱮ ᱜᱚᱲᱚᱜᱼᱟ᱾ ᱚᱠᱟ ᱫᱤᱱ ᱦᱚᱸ ᱚᱴᱤᱯᱤ (OTP), ᱯᱤᱤᱱ (PIN), ᱯᱟᱥᱣᱚᱨᱰ, ᱥᱤᱵᱷᱤᱵᱷᱤ (CVV), ᱯᱩᱨᱟᱹ ᱠᱟᱨᱰ ᱱᱚᱢᱵᱚᱨ ᱥᱮ ᱟᱫᱷᱟᱨ (Aadhaar) ᱱᱚᱢᱵᱚᱨ ᱫᱚ ᱟᱞᱚᱢ ᱥᱚᱫᱚᱜᱼᱟ᱾ ᱠᱚᱵᱚᱪ (Kavach) ᱫᱚ ᱟᱡᱟᱜ ᱛᱮ ᱢᱮᱱᱟᱜᱼᱟ — پولیس ᱵᱟᱝᱟ, ᱥᱚᱨᱠᱟᱨ ᱦᱚᱸ ᱵᱟᱝᱟ᱾",
  "intake.boundaryQ": "ᱢᱟᱲᱟᱝ ᱨᱮ ᱟᱞᱮ ᱞᱮ ᱮᱦᱚᱵᱟ, ᱢᱤᱫᱴᱟᱹᱝ ᱢᱟᱨᱟᱝ ᱠᱟᱛᱷᱟ ᱠᱟᱱᱟ᱾",
  "intake.boundaryBody": "ᱟᱞᱮ ᱫᱚ ᱚᱱᱟ ᱜᱮᱞᱮ ᱠᱩᱠᱞᱤᱭᱟ ᱡᱟᱦᱟᱸ ᱟᱢᱟᱜ ᱠᱮᱥ ᱮ ᱜᱚᱲᱚᱣᱟᱭ᱾ ᱚᱠᱟ ᱚᱠᱛᱚ ᱨᱮᱦᱚᱸ OTP, PIN, ᱯᱟᱥᱣᱟᱨᱰ, CVV, ᱯᱩᱨᱟᱹ ᱠᱟᱨᱰ ᱮᱞᱠᱷᱟ ᱥᱮ Aadhaar ᱮᱞᱠᱷᱟ ᱱᱚᱰᱮ ᱟᱞᱚᱢ ᱥᱮᱭᱟᱨᱟ᱾ Kavach ᱫᱚ ᱟᱡᱟᱜ ᱛᱮ ᱢᱮᱱᱟᱜᱼᱟ, ᱯᱩᱞᱤᱥ ᱥᱮ ᱥᱚᱨᱠᱟᱨᱤ ᱥᱮᱵᱟ ᱫᱚ ᱵᱟᱝ ᱠᱟᱱᱟ᱾",
  "intake.boundaryDetails": "ᱱᱚᱣᱟ ᱯᱨᱚᱴᱳᱴᱟᱭᱤᱯ ᱨᱮ, ᱟᱢᱟᱜ ᱠᱮᱥ ᱫᱚ ᱱᱚᱣᱟ ᱵᱨᱟᱣᱡᱟᱨ ᱨᱮ ᱥᱟᱧᱪᱟᱣ ᱟᱠᱟᱱᱟ᱾ AI ᱛᱟᱞᱟᱛᱮ ᱧᱮᱞ ᱞᱟᱹᱜᱤᱫ ᱟᱢᱟᱜ ᱠᱷᱚᱡ ᱟᱠᱟᱱ ᱚᱞ ᱫᱚ ᱠᱚᱱᱯᱷᱤᱜᱟᱨ ᱟᱠᱟᱱ ᱢᱚᱰᱮᱞ ᱮᱢᱚᱜᱤᱡ ᱴᱷᱮᱱ ᱵᱷᱟᱡᱟ ᱟᱠᱟᱱᱟ᱾ WhatsApp-ᱞᱮᱠᱟᱱ ᱯᱨᱤᱵᱷᱤᱭᱩ ᱫᱚ ᱱᱚᱣᱟ ᱵᱨᱟᱣᱡᱟᱨ ᱨᱮᱜᱮ ᱛᱟᱦᱮᱸᱱᱟ᱾ ᱢᱤᱫᱴᱟᱹᱝ ᱞᱟᱭᱤᱵᱽ Vaani ᱴᱮᱥᱴ ᱠᱚᱞᱵᱮᱠ ᱞᱟᱹᱜᱤᱫ ᱵᱷᱮᱜᱟᱨ ᱠᱷᱚᱡ ᱟᱨ ᱢᱤᱫᱴᱟᱹᱝ ᱟᱞᱟᱣᱞᱤᱥᱴ ᱮᱞᱠᱷᱟ ᱞᱟᱹᱠᱛᱤᱜᱼᱟ᱾",
  "intake.boundaryCta": "ᱤᱧ ᱵᱩᱡᱷᱟᱹᱣ ᱠᱮᱫᱟ — ᱮᱦᱚᱵ ᱢᱮ",
  "intake.safetyQ": "ᱪᱮᱫ ᱟᱢ, ᱥᱮ ᱮᱴᱟᱜ ᱡᱟᱦᱟᱸᱭ ᱜᱮ, ᱱᱤᱛᱚᱜ ᱥᱚᱨᱥᱮ ᱨᱮ ᱢᱮᱱᱟᱜ ᱠᱤᱱᱟ?",
  "intake.safetySafe": "ᱵᱟᱝ, ᱤᱧ ᱫᱚ ᱱᱤᱛᱚᱜ ᱨᱟᱪᱟ ᱨᱮ ᱢᱤᱱᱟᱹᱧᱟ",
