  "intake.emergencyBody": "112 ᱠᱚᱞ ᱢᱮ ᱥᱮ ᱢᱤᱫᱴᱟᱹᱝ ᱨᱟᱪᱟ ᱴᱷᱟᱶ ᱨᱮ ᱪᱟᱞᱟᱜ ᱢᱮ ᱟᱨ ᱡᱟᱦᱟᱸᱭ ᱟᱢ ᱯᱚᱛᱷᱟᱣᱟᱭ ᱩᱱᱤ ᱜᱚᱲᱚ ᱠᱩᱠᱞᱤ ᱢᱮ᱾ ᱱᱚᱣᱟ ᱤᱱᱴᱟᱨᱵᱷᱤᱭᱩ ᱫᱚ ᱵᱤᱯᱚᱫᱽ ᱥᱮᱵᱟ ᱵᱟᱭ ᱵᱷᱟᱡᱟ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
