  "intake.ageQ": "ᱪᱮᱫ ᱱᱚᱣᱟ ᱫᱚ 18 ᱥᱮᱨᱢᱟ ᱠᱷᱚᱱ ᱠᱚᱢ ᱩᱢᱮᱨ ᱨᱤᱱᱤᱡ ᱠᱟᱱᱟ? ᱤᱧ ᱠᱩᱠᱞᱤᱭᱟ ᱪᱮᱫᱟᱜ ᱥᱮ ᱜᱤᱫᱽᱨᱟᱹ-ᱨᱩᱠᱷᱤᱭᱟᱹ ᱟᱨ ᱨᱤᱯᱳᱨᱴ ᱱᱤᱭᱚᱢ ᱫᱚ ᱵᱷᱮᱜᱟᱨ ᱜᱮᱭᱟ᱾",
