  "ev.preserveNote": "ᱡᱩᱫᱤ ᱱᱚᱣᱟ ᱫᱚ ᱨᱟᱠᱷᱟ ᱜᱮᱭᱟ, ᱮᱱᱠᱷᱟᱱ ᱨᱚᱲᱼᱯᱚᱴᱚᱢ ᱵᱟᱝ ᱫᱚᱦᱚ ᱠᱟᱛᱮ ᱥᱮ ᱞᱟᱹᱠᱛᱤᱭᱟᱱ ᱜᱚᱲᱚ ᱵᱟᱝ ᱞᱟᱸᱜᱟ ᱠᱟᱛᱮ ᱢᱩᱲᱩᱛ ᱨᱮᱠᱚᱰ ᱠᱚ ᱫᱚᱦᱚᱭ ᱢᱮ᱾ ᱱᱚᱣᱟ ᱮᱞᱠᱷᱟ ᱫᱚ ᱟᱢᱟᱜ ᱪᱮᱠᱞᱤᱥᱴ ᱮ ᱧᱮᱞᱟ; ᱱᱚᱣᱟ ᱫᱚ ᱟᱹᱱᱟᱹᱨᱤ ᱞᱮᱠᱟᱛᱮ ᱯᱩᱨᱟᱹᱣ ᱟᱠᱟᱱᱟ ᱥᱮ ᱵᱟᱝ ᱚᱱᱟ ᱫᱚ ᱵᱟᱭ ᱴᱷᱟᱹᱣᱠᱟᱭᱟ᱾",
