  "ev.storageNote": "ᱱᱟᱸᱰᱮ ᱡᱚᱱᱚᱲ ᱟᱠᱟᱱ ᱨᱮᱠᱚᱰ ᱠᱚ ᱫᱚ ᱱᱚᱣᱟ ᱵᱨᱟᱣᱡᱟᱨ ᱨᱮᱭᱟᱜ IndexedDB ᱨᱮ ᱟᱥᱚᱞ ᱵᱟᱭᱤᱴᱥ ᱞᱮᱠᱟᱛᱮ ᱥᱟᱸᱪᱟᱣ ᱛᱟᱦᱮᱸᱱᱟ ᱟᱨ SHA-256 ᱛᱮ ᱯᱷᱤᱝᱜᱟᱨᱯᱨᱤᱱᱴ ᱟᱠᱟᱱᱟ᱾ ᱱᱚᱣᱟ ᱠᱚ ᱫᱚ Kavach ᱨᱮᱭᱟᱜ ᱥᱟᱨᱵᱷᱟᱨ ᱥᱮ ᱮᱭᱤ ᱢᱚᱰᱮᱞ ᱴᱷᱮᱱ ᱵᱟᱝ ᱠᱩᱞ ᱟᱠᱟᱱᱟ᱾ ᱥᱟᱭᱤᱴ ᱨᱮᱭᱟᱜ ᱰᱮᱴᱟ  περισᱟᱯᱷ ᱞﻪᱠᱷᱟᱱ ᱱᱚᱣᱟ ᱠᱚ ᱚ(__('ᱢᱚᱪᱷᱟᱜᱼᱟ')); ᱢᱩᱲᱩᱛ ᱨᱮᱠᱚᱰ ᱠᱚᱦᱚᱸ ᱫᱚᱦᱚᱭ ᱢᱮ᱾",
  "ev.manifestTitle": "ᱪᱷᱟᱯᱟ ᱜᱟᱱᱚᱜ ᱨᱮᱠᱚᱰ ᱢᱮᱱᱤᱯᱷᱮᱥᱴ",
  "ev.manifestBody": "ᱟᱢ ᱴᱷᱮᱱ ᱪᱮᱫ ᱢᱮᱱᱟᱜᱼᱟ, ᱪᱮᱫ ᱵᱟᱹᱱᱩᱜᱼᱟ, ᱟᱢᱟᱜ ᱚᱠᱛᱚ ᱟᱨ ᱧᱟᱢᱚᱜ ᱠᱟᱱ ᱯᱷᱤᱝᱜᱟᱨᱯᱨᱤᱱᱴ ᱠᱚ ᱨᱮᱭᱟᱜ ᱢᱤᱫᱴᱟᱹᱝ PDF ᱪᱮᱠᱞᱤᱥᱴ ᱵᱮᱱᱟᱣ ᱢᱮ᱾ PDF ᱨᱮ ᱫᱚ ᱨᱮᱠᱚᱰ ᱯᱷᱟᱭᱤᱞ ᱠᱚ ᱵᱟᱝ ᱛᱟᱦᱮᱸᱱᱟ ᱟᱨ ᱱᱚᱣᱟ ᱫᱚ ᱥᱚᱨᱠᱟᱨᱤ ᱠᱚᱢᱯᱮᱞᱮᱱᱴ ᱵᱟᱝ ᱠᱟᱱᱟ᱾",
