  "ev.tpl.chat_screenshot.why": "ᱚᱠᱚᱭ ᱯᱟᱨᱚᱢᱤᱥ, ᱞᱟᱹᱪᱪᱷᱟᱹᱲᱤ ᱥᱮ ᱦᱩᱫᱤᱥ ᱠᱚ ᱮᱢ ᱟᱠᱟᱫᱟ ᱚᱱᱟ ᱠᱚ ᱨᱩᱠᱷᱤᱭᱟᱹᱭᱟ; ᱥᱠᱨᱤᱱᱥᱚᱴ ᱮᱠᱞᱟ ᱛᱮᱫᱚ ᱵᱟᱭ ᱩᱫᱩᱜᱟ ᱡᱮ ᱮᱠᱟᱣᱩᱱᱴ ᱫᱚ ᱚᱠᱚᱭᱮ ᱪᱟᱪᱞᱟᱣᱮᱫ ᱛᱟᱸᱦᱮᱱᱟ᱾",
